style.css:
@-moz-document domain("youtube.com") {
:root {
    --my-text: #FFB7C5;
    --my-secondary: #D65A85;
}

/* Main text colors */
html, html[dark], body, ytd-app, ytd-watch-metadata {
    --tffc2fd3a644f6275: var(--my-text) !important;
    --t4a6da19e16bf221a: var(--my-secondary) !important;
    --yt-spec-text-primary: var(--my-text) !important;
    --yt-spec-text-secondary: var(--my-secondary) !important;
}

/* Titles, sidebar and comments */
html body ytd-app .ytLockupMetadataViewModelTitle,
html body ytd-app .ytLockupMetadataViewModelTitle span,
html body ytd-app #video-title,
html body ytd-app #video-title-link,
ytd-watch-metadata,
ytd-watch-metadata h1,
ytd-watch-metadata h1 yt-formatted-string,
ytd-guide-entry-renderer,
ytd-guide-entry-renderer #endpoint,
ytd-guide-entry-renderer yt-formatted-string,
ytd-guide-section-renderer #guide-section-title,
ytd-mini-guide-entry-renderer span,
#content-text,
#content-text span,
#author-text,
#description,
#description span {
    color: var(--my-text) !important;
    -webkit-text-fill-color: var(--my-text) !important;
}

/* Channel names and video information */
html body ytd-app .ytLockupMetadataViewModelMetadata,
html body ytd-app .ytLockupMetadataViewModelMetadata span,
html body ytd-app .ytLockupMetadataViewModelMetadata a,
html body ytd-app #channel-name a,
html body ytd-app #metadata-line,
html body ytd-app #metadata-line span {
    --t4a6da19e16bf221a: var(--my-secondary) !important;
    color: var(--my-secondary) !important;
    -webkit-text-fill-color: var(--my-secondary) !important;
}

/* Search bar */
#search-input input,
yt-searchbox input {
    color: var(--my-text) !important;
    caret-color: var(--my-text) !important;
}

#search-input input::placeholder,
yt-searchbox input::placeholder {
    color: var(--my-secondary) !important;
}
}
